#!/usr/bin/env python3
"""Build the TempleOS Mobile app icon for iOS and Android from TempleOS.png.

    TempleOS.png -> pixel-art reconstruction -> normalized 1024 master
                 -> iOS AppIcon + Android adaptive icon -> validation and previews

Usage: build_app_icon.py [--source PATH] [--check]

  --source PATH   artwork to build from (default: TempleOS.png at the repository root)
  --check         build in memory and fail if any generated file differs from the one
                  on disk (reproducibility check; writes nothing)

Writes (docs/app-icon/README.md):
  shared/app-icon/              reconstructed pixel art, 1024 master, palette, layout
  temple_os_swift/.../AppIcon.appiconset/AppIcon-1024.png
  temple_os_kotlin/app/src/main/res/mipmap-*/ic_launcher_{foreground,monochrome}.png,
      drawable/ic_launcher_background.xml, mipmap-anydpi-v26/ic_launcher.xml
  temple_os_kotlin/app/src/main/ic_launcher-playstore.png
  docs/app-icon/                previews, contact sheet, color and validation reports
Exit status 1 when a validation check fails.

Requires Python 3.9+, Pillow and numpy. The source image is never modified.
"""
import argparse, hashlib, io, json, os, sys

import numpy as np
from PIL import Image

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)

import compose as C         # noqa: E402
import layout as L          # noqa: E402
import reconstruct as R     # noqa: E402
import render as RD         # noqa: E402
import validate as V        # noqa: E402

GENERATED = 'Generated by tools/app-icon/build_app_icon.py from TempleOS.png (docs/app-icon/README.md); do not edit.'


class Output:
    """Writes generated files, or in --check mode compares them with the files on disk."""

    def __init__(self, check):
        self.check, self.written, self.differs, self.removed = check, [], [], []

    def emit(self, rel, data, doc=False):
        path = os.path.join(ROOT, rel)
        old = open(path, 'rb').read() if os.path.exists(path) else None
        if self.check:
            # documentation previews contain rendered captions (font rasterization differs
            # between Pillow builds), so --check covers the build outputs only
            if not doc and not same(old, data, rel):
                self.differs.append(rel)
            return
        if old != data:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, 'wb') as f:
                f.write(data)
        self.written.append(rel)

    def remove(self, rel):
        path = os.path.join(ROOT, rel)
        if os.path.exists(path):
            if self.check:
                self.differs.append(rel + ' (stale, should be removed)')
            else:
                os.remove(path)
                self.removed.append(rel)


def same(old, new, rel):
    """Equal bytes, or for PNG equal decoded pixels (zlib output can differ between installs)."""
    if old == new:
        return True
    if old is None or not rel.endswith('.png'):
        return False
    a, b = Image.open(io.BytesIO(old)), Image.open(io.BytesIO(new))
    return a.mode == b.mode and a.size == b.size and np.array_equal(np.asarray(a), np.asarray(b))


def png(arr):
    buf = io.BytesIO()
    Image.fromarray(arr).save(buf, 'PNG', optimize=True)
    return buf.getvalue()


def text(s):
    return s.encode('utf-8')


def hexcolor(rgb):
    return '#%02X%02X%02X' % tuple(rgb)

# ------------------------------------------------------------------------- layout
# Placement uses the "kept" artwork: everything except the sword, which deliberately runs
# out of the frame (compose.py). The composition center is shared by both platforms.

def ios_layout(corners, center, kept_bbox, cfg, pad):
    """Largest integer logical-pixel size that keeps the kept artwork inside the iOS masks
    (and the Play listing mask, which reuses this composition) with the required clearance."""
    size = cfg['canvas_px']
    masks = dict(L.IOS_MASKS, **{'play-store-rounded-square': L.PLAY_MASK})
    for cell in range(cfg['max_cell_px'], 2, -1):
        # even origin: the 512 px Play icon (half scale) then stays on whole pixels too
        ox, oy = (2 * round((size / 2 - c * cell) / 2) for c in center)
        x0, x1, y0, y1 = kept_bbox
        margins = [x0 * cell + ox, size - (x1 * cell + ox), y0 * cell + oy, size - (y1 * cell + oy)]
        clear = L.report(corners, cell / size, (ox / size, oy / size), masks)
        if min(margins) / size >= cfg['min_clearance'] and \
                min(v['min_clearance'] for v in clear.values()) >= cfg['min_clearance']:
            return {'canvas_px': size, 'cell_px': cell, 'origin_px': [ox, oy],
                    'kept_art_px': [(x1 - x0) * cell, (y1 - y0) * cell],
                    'kept_art_edge_margins_px': dict(zip(('left', 'right', 'top', 'bottom'), margins)),
                    'mask_clearance_px': {k: round(v['min_clearance'] * size, 1) for k, v in clear.items()},
                    'mask_clearance_at_logical_px': {k: [c - pad for c in v['at_logical']] for k, v in clear.items()}}
    raise SystemExit('no iOS layout satisfies the clearance in icon_config.json')


def android_layout(corners, center, kept_bbox, cfg, pad):
    """Scale so the farthest kept pixel is art_radius_dp from the icon center (the 66 dp safe zone)."""
    far = float(np.sqrt(((corners - np.array(center)) ** 2).sum(1)).max())
    cell = cfg['art_radius_dp'] / 72 / far                      # icon units (72 dp viewport = 1)
    origin = (0.5 - center[0] * cell, 0.5 - center[1] * cell)
    masks = dict(L.ANDROID_MASKS, **{'android-safe-zone-66dp': L.ANDROID_SAFE_ZONE})
    clear = L.report(corners, cell, origin, masks)
    x0, x1, y0, y1 = kept_bbox
    lay = {'layer_dp': 108, 'viewport_dp': 72, 'cell_dp': round(cell * 72, 6), 'origin_dp': [18 + o * 72 for o in origin],
           'kept_art_dp': [round((x1 - x0) * cell * 72, 2), round((y1 - y0) * cell * 72, 2)],
           'farthest_kept_point_dp': round(cfg['art_radius_dp'], 3),
           'mask_clearance_dp': {k: round(v['min_clearance'] * 72, 2) + 0.0 for k, v in clear.items()},
           'mask_clearance_at_logical_px': {k: [c - pad for c in v['at_logical']] for k, v in clear.items()}}
    if lay['mask_clearance_dp']['android-circle'] < cfg['min_circle_clearance_dp'] or \
            lay['mask_clearance_dp']['android-safe-zone-66dp'] < 0:
        raise SystemExit('Android layout violates the circle clearance or the 66 dp safe zone')
    return lay, cell, origin


def monochrome_mask(labels, palette):
    """Themed-icon silhouette: every art pixel, minus the lettering outline (it separates the
    letters from the sword behind them), minus blade pixels touching gold (so the guard and
    the roof stay distinct from the blade)."""
    names = [p['name'] for p in palette]
    fam = np.array([p['family'] for p in palette])
    black, text_y = names.index('black'), names.index('text_yellow')
    H, W = labels.shape
    on = labels != 0
    pad = np.pad(labels, 1, constant_values=0)
    near_text = np.zeros_like(on)
    near_gold = np.zeros_like(on)
    for dy in (-1, 0, 1):
        for dx in (-1, 0, 1):
            sh = pad[1 + dy:1 + dy + H, 1 + dx:1 + dx + W]
            near_text |= sh == text_y
            if abs(dy) + abs(dx) == 1:
                near_gold |= fam[sh] == 'gold'
    on &= ~((labels == black) & near_text)
    on &= ~((fam[labels] == 'silver') & near_gold)
    return on

# -------------------------------------------------------------------------- build

def main():
    ap = argparse.ArgumentParser(description=__doc__.split('\n')[0])
    ap.add_argument('--source', default=None)
    ap.add_argument('--check', action='store_true')
    args = ap.parse_args()
    cfg = json.load(open(os.path.join(HERE, 'icon_config.json')))
    src_path = os.path.abspath(args.source or os.path.join(ROOT, cfg['source']))
    src_bytes = open(src_path, 'rb').read()
    src = Image.open(io.BytesIO(src_bytes))
    a = np.asarray(src.convert('RGB')).astype(np.float64)
    out = Output(args.check)
    S, D = cfg['outputs']['shared'], cfg['outputs']['docs']

    # 1. reconstruction
    rec = R.reconstruct(a, cfg['palette_seeds'], tuple(cfg['grid_pitch_range_px']))
    labels, palette = rec['labels'], rec['palette']
    pal = np.array([p['rgb'] for p in palette], np.uint8)
    bg = palette[0]['rgb']

    # 2. composition: the sword runs out of the frame; the rest is placed per platform
    fam = np.array([p['family'] for p in palette])
    lay = cfg['layout']
    pad = lay['canvas_pad']
    if lay['sword'] == 'bleed':
        art, sword, sword_report = C.extend_sword(labels, fam, pad)
    elif lay['sword'] == 'whole':
        art, sword_report = np.pad(labels, pad), {'mode': 'whole'}
        sword = np.zeros(art.shape, bool)                       # nothing is excused from the masks
    else:
        raise SystemExit('layout.sword must be "bleed" or "whole"')
    kept = (art != 0) & ~sword
    corners = L.art_corners(kept.astype(np.int32))
    ys, xs = np.nonzero(kept)
    kept_bbox = (int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1)
    cx, cy, text_c = C.focus_center(labels, fam, lay['center_blend'])
    center = (cx + pad, cy + pad)
    ios = ios_layout(corners, center, kept_bbox, lay['ios'], pad)
    android, a_cell, a_origin = android_layout(corners, center, kept_bbox, lay['android'], pad)
    wordmark = (int(np.nonzero(fam[labels] == 'text')[1].min()) - 1, int(np.nonzero(fam[labels] == 'text')[1].max()) + 2)
    comp = {'sword': sword_report, 'center_logical_px': [round(cx, 2), round(cy, 2)],
            'wordmark_center_logical_px': [round(text_c[0], 2), round(text_c[1], 2)],
            'wordmark_outline_columns': list(wordmark)}
    ios['wordmark_width_pct'] = round((wordmark[1] - wordmark[0]) * ios['cell_px'] / ios['canvas_px'] * 100, 1)
    ios['wordmark_center_below_icon_center_px'] = round((text_c[1] - cy) * ios['cell_px'], 1)
    android['wordmark_width_pct_of_viewport'] = round((wordmark[1] - wordmark[0]) * a_cell * 100, 1)
    android['wordmark_center_below_icon_center_dp'] = round((text_c[1] - cy) * a_cell * 72, 2)

    # 3. canonical outputs
    pixels = pal[labels]
    master = RD.render_rgba(art, pal, ios['canvas_px'], ios['cell_px'], ios['origin_px'], transparent=(), canvas=bg)[..., :3]
    out.emit(f'{S}/TempleOS-pixels.png', png(pixels))
    ax0, ay0 = (int(np.floor((-0.25 - o) / a_cell)) for o in a_origin)         # the 108 dp Android layer,
    span = int(np.ceil(1.5 / a_cell)) + 1                                      # in logical pixels
    out.emit(f'{S}/TempleOS-icon-art.png', png(pal[art[max(0, ay0):ay0 + span, max(0, ax0):ax0 + span]]))
    out.emit(f'{S}/AppIcon-1024.png', png(master))
    meta = {'$comment': GENERATED,
            'source': {'path': os.path.relpath(src_path, ROOT), 'sha256': hashlib.sha256(src_bytes).hexdigest(),
                       'size': list(src.size), 'mode': src.mode},
            'logical_size': [int(labels.shape[1]), int(labels.shape[0])],
            'reconstruction': rec['report'],
            'palette': [{k: p[k] for k in ('name', 'family', 'role', 'rgb', 'cells', 'spread', 'logical_pixels') if k in p}
                        | {'hex': hexcolor(p['rgb'])} for p in palette]}
    out.emit(f'{S}/icon-palette.json', text(json.dumps(meta, indent=2) + '\n'))
    out.emit(f'{S}/icon-layout.json', text(json.dumps({'$comment': GENERATED, 'composition': comp, 'ios': ios,
                                                        'android': android}, indent=2) + '\n'))

    # 4. iOS: single-size universal icon (Xcode derives every device size from it)
    iset = cfg['ios']['appiconset']
    out.emit(f"{iset}/{cfg['ios']['filename']}", png(master))
    out.emit(f'{iset}/Contents.json', text(            # Xcode's own layout, unchanged when the file name is
        '{\n  "images" : [\n'
        f'    {{ "filename" : "{cfg["ios"]["filename"]}", "idiom" : "universal", "platform" : "ios", "size" : "1024x1024" }}\n'
        '  ],\n  "info" : { "author" : "xcode", "version" : 1 }\n}\n'))

    # 5. Android adaptive icon (minSdk 26: every supported device uses mipmap-anydpi-v26)
    res = cfg['android']['res_dir']
    mono = monochrome_mask(art, palette)
    fg_by_density = {}
    for dname, d in cfg['android']['densities'].items():
        size = int(round(108 * d))
        cell = a_cell * 72 * d
        origin = (a_origin[0] * 72 * d + 18 * d, a_origin[1] * 72 * d + 18 * d)
        fg = RD.render_rgba(art, pal, size, cell, origin, transparent=(0,))
        alpha = RD.render_alpha(mono, size, cell, origin)
        mono_img = np.dstack([np.full((size, size, 3), 255, np.uint8), alpha])
        out.emit(f'{res}/mipmap-{dname}/ic_launcher_foreground.png', png(fg))
        out.emit(f'{res}/mipmap-{dname}/ic_launcher_monochrome.png', png(mono_img))
        fg_by_density[dname] = (fg, alpha)
    out.emit(f'{res}/drawable/ic_launcher_background.xml', text(
        '<?xml version="1.0" encoding="utf-8"?>\n'
        f'<!-- {GENERATED} -->\n'
        '<!-- Background layer of the adaptive launcher icon: the cyan of the icon artwork. -->\n'
        '<shape xmlns:android="http://schemas.android.com/apk/res/android" android:shape="rectangle">\n'
        f'    <solid android:color="{hexcolor(bg)}" />\n'
        '</shape>\n'))
    out.emit(f'{res}/mipmap-anydpi-v26/ic_launcher.xml', text(
        '<?xml version="1.0" encoding="utf-8"?>\n'
        f'<!-- {GENERATED} -->\n'
        '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
        '    <background android:drawable="@drawable/ic_launcher_background" />\n'
        '    <foreground android:drawable="@mipmap/ic_launcher_foreground" />\n'
        '    <monochrome android:drawable="@mipmap/ic_launcher_monochrome" />\n'
        '</adaptive-icon>\n'))
    out.remove(f'{res}/drawable/ic_launcher_foreground.xml')            # the previous vector placeholder
    ps = cfg['android']['playstore']
    k = ps['size'] / ios['canvas_px']                                   # Play listing icon: iOS composition
    store = RD.render_rgba(art, pal, ps['size'], ios['cell_px'] * k,
                           (ios['origin_px'][0] * k, ios['origin_px'][1] * k), transparent=(), canvas=bg)
    out.emit(ps['path'], png(store))                                    # Play asks for a 32-bit PNG: RGBA, opaque

    # 6. validation, previews, reports
    ctx = dict(root=ROOT, cfg=cfg, src=a.astype(np.uint8), src_info=meta['source'], rec=rec, pal=pal, master=master,
               art=art, sword=sword, kept=kept, comp=comp, ios=ios, android=android, a_cell=a_cell, a_origin=a_origin,
               mono=mono, store=store, fg_by_density=fg_by_density, out=out)
    errors = V.run(ctx)

    if args.check:
        if out.differs:
            print('out of date:\n  ' + '\n  '.join(out.differs))
            errors.append('generated files differ from the build')
        else:
            print('all generated files are up to date')
    else:
        print(f'{len(out.written)} files generated' + (f', removed {", ".join(out.removed)}' if out.removed else ''))
    for e in errors:
        print('ERROR:', e)
    sys.exit(1 if errors else 0)


if __name__ == '__main__':
    main()
